const dictionaries = Object.fromEntries(["si", "ta"].map((language, index) => [
  language,
  Object.fromEntries(entries.map(([source, sinhala, tamil]) => [source, index === 0 ? sinhala : tamil])),
]));
const orderedDictionaries = Object.fromEntries(Object.entries(dictionaries).map(([language, dictionary]) => [
  language,
  Object.entries(dictionary).sort((a, b) => b[0].length - a[0].length),
]));

const attributes = ["aria-label", "aria-description", "title", "placeholder", "alt", "data-label", "content"];
const originalText = new WeakMap();
const lastText = new WeakMap();
const originalAttributes = new WeakMap();
const lastAttributes = new WeakMap();

function translateValue(value, dictionary, orderedEntries, reverseDictionary) {
  const leading = value.match(/^\s*/)?.[0] || "";
  const trailing = value.match(/\s*$/)?.[0] || "";
  const core = value.slice(leading.length, value.length - trailing.length || undefined);
  const english = reverseDictionary.get(core) || core;
  const exact = dictionary[english];
  if (exact) return `${leading}${exact}${trailing}`;

  let translated = english;
  for (const [source, target] of orderedEntries) {
    if (source.length < 4) continue;
    translated = translated.split(source).join(target);
  }
  return `${leading}${translated}${trailing}`;
}

export function installTranslations(language) {
  const dictionary = dictionaries[language] || {};
  const orderedEntries = orderedDictionaries[language] || [];
  const reverseDictionary = new Map(Object.entries(dictionary).map(([source, target]) => [target, source]));

  const translateTextNode = node => {
    const current = node.nodeValue;
    const original = current === lastText.get(node) ? originalText.get(node) : current;
    originalText.set(node, original);
    const translated = translateValue(original, dictionary, orderedEntries, reverseDictionary);
    if (translated !== current) {
      lastText.set(node, translated);
      node.nodeValue = translated;
    } else {
      lastText.set(node, current);
    }
  };

  const translateElement = element => {
    for (const attribute of attributes) {
      if (!element.hasAttribute(attribute)) continue;
      const current = element.getAttribute(attribute);
      let originals = originalAttributes.get(element);
      let previous = lastAttributes.get(element);
      if (!originals) {
        originals = new Map();
        previous = new Map();
        originalAttributes.set(element, originals);
        lastAttributes.set(element, previous);
      }
      const original = current === previous.get(attribute) ? originals.get(attribute) : current;
      originals.set(attribute, original);
      const translated = translateValue(original, dictionary, orderedEntries, reverseDictionary);
      previous.set(attribute, translated);
      if (translated !== current) element.setAttribute(attribute, translated);
    }
  };

  const translateTree = node => {
    if (node.nodeType === Node.TEXT_NODE) {
      translateTextNode(node);
      return;
    }
    if (node.nodeType !== Node.ELEMENT_NODE && node.nodeType !== Node.DOCUMENT_NODE) return;
    if (node.nodeType === Node.ELEMENT_NODE) translateElement(node);
    const walker = document.createTreeWalker(node, NodeFilter.SHOW_TEXT);
    while (walker.nextNode()) translateTextNode(walker.currentNode);
    if (node.querySelectorAll) {
      for (const element of node.querySelectorAll(attributes.map(name => `[${name}]`).join(","))) {
        translateElement(element);
      }
    }
  };

  document.documentElement.lang = language;
  translateTree(document.documentElement);
  const observer = new MutationObserver(mutations => {
    for (const mutation of mutations) {
      if (mutation.type === "characterData") translateTextNode(mutation.target);
      if (mutation.type === "attributes") translateElement(mutation.target);
      for (const node of mutation.addedNodes || []) translateTree(node);
    }
  });
  observer.observe(document.documentElement, {
    subtree: true,
    childList: true,
    characterData: true,
    attributes: true,
    attributeFilter: attributes,
  });
  return () => observer.disconnect();
}
